const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Bear Island location and points 100 km and 250 km south
  const bearIsland = ee.Geometry.Point([19.0, 74.5]);
  // 1 degree latitude ≈ 111 km
  const point100km = bearIsland.translate(0, -100000); // south: negative y
  const point250km = bearIsland.translate(0, -250000);

  // Buffers to get small water regions (1 km radius)
  const region100 = point100km.buffer(1000);
  const region250 = point250km.buffer(1000);

  // 2. Date: August 5, 2025 is future; use same date in 2023 with 3-day window
  const startDate = '2023-08-03';
  const endDate = '2023-08-07';

  // Sentinel-2 Level 2A (surface reflectance)
  let collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterDate(startDate, endDate)
    .filterBounds(region100.union(region250))
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

  // Check if collection is empty
  let collSize = collection.size().getInfo();
  console.log(`Sentinel-2 images found: ${collSize}`);

  if (collSize === 0) {
    // Try Landsat 9 as fallback (similar blue band)
    console.log('Trying Landsat 9...');
    collection = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
      .filterDate(startDate, endDate)
      .filterBounds(region100.union(region250))
      .filter(ee.Filter.lt('CLOUD_COVER', 30));
    collSize = collection.size().getInfo();
    console.log(`Landsat 9 images found: ${collSize}`);
    if (collSize === 0) {
      console.log('<answer>C1</answer>');
      return;
    }
    // For Landsat 9, use SR_B2 (blue band)
    var blueBand = 'SR_B2';
    var scale = 30; // Landsat resolution
    var cloudMask = function(image) {
      var qa = image.select('QA_PIXEL');
      var cloud = qa.bitwiseAnd(1 << 3).or(qa.bitwiseAnd(1 << 4));
      return image.updateMask(cloud.not());
    };
    collection = collection.map(cloudMask);
  } else {
    // For Sentinel-2, use B2 (blue band)
    var blueBand = 'B2';
    var scale = 10; // Sentinel-2 resolution
    var cloudMask = function(image) {
      var qa = image.select('QA60');
      var cloud = qa.bitwiseAnd(1 << 10).or(qa.bitwiseAnd(1 << 11));
      return image.updateMask(cloud.not());
    };
    collection = collection.map(cloudMask);
  }

  // 3. Get median composite (to minimize cloud residuals)
  const composite = collection.median();

  // 4. Extract blue band reflectance for each region
  const extractStats = function(region, label) {
    // Count valid pixels
    const count = composite.select(blueBand)
      .reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: region,
        scale: 3000, // Use larger scale to avoid memory/timeout
        maxPixels: 1e9
      }).get(blueBand);
    const mean = composite.select(blueBand)
      .reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: region,
        scale: 3000,
        maxPixels: 1e9
      }).get(blueBand);
    return {label: label, count: count, mean: mean};
  };

  const stats100 = extractStats(region100, '100km south');
  const stats250 = extractStats(region250, '250km south');

  // Get values
  const count100 = stats100.count.getInfo();
  const count250 = stats250.count.getInfo();
  const mean100 = stats100.mean.getInfo();
  const mean250 = stats250.mean.getInfo();

  console.log(`${stats100.label}: Valid pixels = ${count100}, Mean blue reflectance = ${mean100 ? mean100.toFixed(4) : 'null'}`);
  console.log(`${stats250.label}: Valid pixels = ${count250}, Mean blue reflectance = ${mean250 ? mean250.toFixed(4) : 'null'}`);

  // 5. Check for no valid pixels (C2)
  if (count100 === 0 || count250 === 0) {
    console.log('<answer>C2</answer>');
    return;
  }

  // 6. Check for invalid calculations (C3)
  if (mean100 === null || mean250 === null || 
      isNaN(mean100) || isNaN(mean250) ||
      mean100 < 0 || mean100 > 1 || 
      mean250 < 0 || mean250 > 1) {
    console.log('<answer>C3</answer>');
    return;
  }

  // 7. Compare: does 100 km south have higher blue reflectance (more turquoise-blue)?
  if (mean100 > mean250) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
